def main():
    args = sys.argv[1:]
    fontsdir = None
    if "--fonts" in args:
        i = args.index("--fonts"); fontsdir = pathlib.Path(args[i + 1]); del args[i:i + 2]
    if len(args) != 3:
        print(__doc__); sys.exit(1)
    draft, icondir, out = pathlib.Path(args[0]), pathlib.Path(args[1]), pathlib.Path(args[2])
    html = draft.read_text(encoding="utf-8")

if fontsdir:
    for tok, fn in (("%%FONT_DISPLAY%%", "Geist.woff2"), ("%%FONT_JBM%%", "JetBrainsMono.woff2")):
        if tok in html:
            html = html.replace(tok, b64(fontsdir / fn))

for f in sorted(icondir.iterdir()):
    if f.suffix.lstrip(".") not in MIME:
        continue
    tok = f"%%ICON_{f.stem}%%"
    if tok in html:
        html = html.replace(tok, f"data:{MIME[f.suffix.lstrip('.')]};base64,{b64(f)}")

import base64, pathlib, re, sys

MIME = {"svg": "image/svg+xml", "png": "image/png", "webp": "image/webp",
        "jpg": "image/jpeg", "jpeg": "image/jpeg"}

def b64(p): return base64.b64encode(pathlib.Path(p).read_bytes()).decode()

def main():
    args = sys.argv[1:]
    sel, scale, full, single = ".canvas", 2, False, False
    if "--selector" in args:
        i = args.index("--selector"); sel = args[i + 1]; del args[i:i + 2]
    if "--scale" in args:
        i = args.index("--scale"); scale = float(args[i + 1]); del args[i:i + 2]
    if "--full-page" in args:
        args.remove("--full-page"); full = True
    if "--single" in args:
        args.remove("--single"); single = True
    if len(args) != 2:
        print(__doc__); sys.exit(1)
    src, out = pathlib.Path(args[0]).resolve(), pathlib.Path(args[1])

def shoot(page, path):
    if full:
        page.screenshot(path=str(path), full_page=True)
    else:
        el = page.query_selector(sel)
        if not el:
            sys.exit(f"selector {sel!r} not found in {src.name}")
        el.screenshot(path=str(path))
    print(f"rendered {path}")
